int vfs_rename(struct inode *old_dir, struct dentry *old_dentry,
               struct inode *new_dir, struct dentry *new_dentry,
               struct inode **delegated_inode, unsigned int flags)
{
    int error;

    if (old_dentry->d_inode && !old_dir->i_nlink)
        return -EINVAL;

    error = inode_permission(old_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    error = inode_permission(new_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    if (S_ISDIR(old_dentry->d_inode->i_mode)) {
        error = inode_permission(old_dentry->d_inode, MAY_EXEC);
        if (error)
            return error;
    }

    if (new_dentry->d_inode) {
        error = may_delete(new_dir, new_dentry);
        if (error)
            return error;
    } else {
        error = may_create(new_dir, new_dentry);
        if (error)
            return error;
    }

    if (flags & RENAME_EXCHANGE) {
        struct inode *other_inode = new_dentry->d_inode;
        if (other_inode && !other_inode->i_nlink)
            return -EBUSY;
    }

    error = security_dentry_rename(old_dir, old_dentry, new_dir, new_dentry, flags);
    if (error)
        return error;

    if (IS_DEADDIR(old_dir) || IS_DEADDIR(new_dir))
        return -ENOENT;

    if (flags & RENAME_NOREPLACE && new_dentry->d_inode)
        return -EEXIST;

    if (flags & RENAME_EXCHANGE) {
        error =vfs_rename_exchange(old_dir, old_dentry, new_dir, new_dentry, delegated_inode);
    } else {
        error = vfs_rename_old(old_dir, old_dentry, new_dir, new_dentry, delegated_inode);
    }

    if (!error) {
        d_move(old_dentry, new_dentry);
        fsnotify_move(old_dir, new_dir, old_dentry, new_dentry);
    }

    return error;
}

int vrename(struct inode *old_dir, struct dentry *old_dentry,
            struct inode *new_dir, struct dentry *new_dentry,
            struct inode **delegated_inode, unsigned int flags)
{
    struct inode *old_inode = old_dentry->d_inode;
    struct inode *new_inode = new_dentry->d_inode;
    int error;

    /* Check if source and target are the same */
    if (old_inode == new_inode && old_dir == new_dir &&
        !dentry_needs_revalidate(old_dentry) && !dentry_needs_revalidate(new_dentry))
        return 0;

    /* Check permissions for deletion and creation */
    error = -EACCES;
    if (!inode_is_credential_ok(old_dir, MAY_WRITE | MAY_EXEC))
        goto out;
    if (!inode_is_credential_ok(new_dir, MAY_WRITE | MAY_EXEC))
        goto out;

    /* Handle directory special cases and link limits */
    if (S_ISDIR(old_inode->i_mode)) {
        if (old_inode == new_inode && flags & RENAME_EXCHANGE) {
            if (!inode_is_credential_ok(new_inode, MAY_WRITE))
                goto out;
        }
        if (new_inode && !inode_is_credential_ok(new_inode, MAY_WRITE))
            goto out;
    }

    /* Perform the rename operation */
    error = -ENOSYS;
    if (!old_inode->i_op->rename)
        goto out;

    if (flags & RENAME_EXCHANGE)
        error = old_inode->i_op->rename(old_dir, old_dentry, new_dir, new_dentry);
    else
        error = generic_rename(old_dir, old_dentry, new_dir, new_dentry);

    if (!error) {
        /* Notify filesystem of the move */
        d_move(old_dentry, new_dentry);
        inode_notify_move(old_inode, new_inode);
    }

out:
    return error;
}

int vfs_rename(struct inode *old_dir, struct dentry *old_dentry,
               struct inode *new_dir, struct dentry *new_dentry,
               struct inode **delegated_inode, unsigned int flags)
{
    int error;

    if (old_dentry == new_dentry)
        return 0;

    error = inode_permission(old_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    error = inode_permission(new_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    if (S_ISDIR(old_dentry->d_inode->i_mode)) {
        if (flags & RENAME_EXCHANGE) {
            error = -EEXIST;
            if (new_dentry->d_inode)
                return error;
        }
    }

    error = -EMLINK;
    if (old_dir->i_nlink >= (unsigned short)~0)
        return error;

    if (new_dentry->d_inode) {
        error = -ENOTEMPTY;
        if (S_ISDIR(new_dentry->d_inode->i_mode) &&
            !inode_permission(new_dentry->d_inode, MAY_EXEC))
            return error;
    }

    error = security_inode_rename(old_dir, old_dentry, new_dir, new_dentry,
                                  flags);
    if (error)
        return error;

    lock_kernel();
    error = old_dir->i_op->rename(old_dir, old_dentry, new_dir, new_dentry);
    unlock_kernel();

    if (!error)
        fsnotify_move(old_dir, new_dir, old_dentry, new_dentry);

    return error;
}

int vfat_rename(struct inode *old_dir, struct dentry *old_dentry, struct inode *new_dir, struct dentry *new_dentry, struct inode **delegated_inode, unsigned int flags)
{
    int error;
    struct inode *old_inode = old_dentry->d_inode;
    struct inode *new_inode = new_dentry->d_inode;
    struct super_block *sb = old_dir->i_sb;

    if (old_inode == new_inode)
        return 0;

    if (IS_APPEND(old_dir) || IS_IMMUTABLE(old_dir))
        return -EPERM;

    if (IS_APPEND(new_dir) || IS_IMMUTABLE(new_dir))
        return -EPERM;

    if (flags & RENAME_EXCHANGE) {
        if (!new_inode)
            return -ENOENT;
        if (IS_APPEND(new_inode) || IS_IMMUTABLE(new_inode))
            return -EPERM;
    }

    if (S_ISDIR(old_inode->i_mode)) {
        if (old_inode->i_nlink >= (1U << 16) - 1)
            return -EMLINK;
    }

    if (new_inode) {
        if (IS_APPEND(new_inode) || IS_IMMUTABLE(new_inode))
            return -EPERM;
        if (IS_DIRSYNC(new_inode))
            error = dquot_alloc_inode(new_inode);
        if (error)
            return error;
    } else {
        if (IS_DIRSYNC(new_dir))
            error = dquot_alloc_inode(new_dir);
        if (error)
            return error;
    }

    if (flags & RENAME_NOREPLACE && new_inode)
        return -EEXIST;

    if (new_inode) {
        error = inode_lock_nested(new_inode, I_MUTEX_RIGHT(new_inode));
        if (error)
            return error;
    }

    error = inode_lock(old_inode);
    if (error) {
        if (new_inode)
            inode_unlock(new_inode);
        return error;
    }

    error = -EPERM;
    if (S_ISDIR(old_inode->i_mode)) {
        if (IS_RDONLY(sb))
            goto out;
        if (old_dir != new_dir && !capable(CAP_FOWNER))
            goto out;
    }

    if (S_ISDIR(old_inode->i_mode)) {
        if (old_inode->i_nlink >= (1U << 16) - 1)
            goto out;
    }

    if (new_inode) {
        if (S_ISDIR(new_inode->i_mode)) {
            if (IS_RDONLY(sb))
                goto out;
            if (new_dir != old_inode && !capable(CAP_FOWNER))
                goto out;
        }

        error = vfs_unlink(new_dir, new_dentry);
        if (error)
            goto out;
    }

    error = vfs_rename(old_dir, old_dentry, new_dir, new_dentry, flags, delegated_inode);
    if (error)
        goto out;

    if (new_inode) {
        d_instantiate(new_dentry, new_inode);
        if (S_ISDIR(new_inode->i_mode)) {
            new_inode->i_ctime = current_time(new_inode);
        }
    }

    if (old_inode->i_nlink == 0) {
        old_inode->i_nlink = 1;
    }

    if (S_ISDIR(old_inode->i_mode)) {
        old_inode->i_ctime = current_time(old_inode);
    }

    error = 0;

out:
    inode_unlock(old_inode);
    if (new_inode)
        inode_unlock(new_inode);
    if (error)
        dquot_free_inode(new_inode ? new_inode : new_dir);
    return error;
}

int vfs_rename(struct inode *old_dir, struct dentry *old_dentry,
               struct inode *new_dir, struct dentry *new_dentry,
               struct inode **delegated_inode, unsigned int flags)
{
    int error;

    if (old_dentry->d_inode == new_dentry->d_inode &&
        !d_need_retry(new_dentry))
        return 0;

    error = inode_permission(old_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    error = inode_permission(new_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    if (flags & RENAME_EXCHANGE) {
        error = inode_permission(new_dir, MAY_WRITE | MAY_EXEC);
        if (error)
            return error;
    }

    if (S_ISDIR(old_dentry->d_inode->i_mode)) {
        error = inode_permission(old_dentry->d_inode, MAY_EXEC);
        if (error)
            return error;
    }

    if (old_dentry->d_inode->i_nlink >= INT_MAX)
        return -EMLINK;

    if (new_dentry->d_inode) {
        error = inode_permission(new_dir, MAY_WRITE | MAY_EXEC);
        if (error)
            return error;

        if (S_ISDIR(new_dentry->d_inode->i_mode)) {
            error = inode_permission(new_dentry->d_inode, MAY_EXEC);
            if (error)
                return error;
        }
    }

    error = old_dir->i_op->rename(old_dir, old_dentry, new_dir, new_dentry, flags);
    if (error)
        return error;

    if (delegated_inode && *delegated_inode)
        put_delegated_inode(*delegated_inode);

    d_move(old_dentry, new_dentry);

    if (S_ISDIR(old_dentry->d_inode->i_mode))
        fsnotify_move(old_dir, new_dir, old_dentry, new_dentry);

    return 0;
}
